<?php session_start();header('Content-Type: application/json');try{$c=require __DIR__.'/config.php';$p=new PDO("mysql:host={$c['db_host']};dbname={$c['db_name']};charset=utf8mb4",$c['db_user'],$c['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$d=json_decode(file_get_contents('php://input'),true)??[];$a=$_GET['action']??'';if($a==='register'){$s=$p->prepare("SELECT id FROM users WHERE email=?");$s->execute([$d['email']??'']);if($s->fetch())throw new Exception('An account with this email already exists.');$s=$p->prepare("INSERT INTO users(name,phone,email,password_hash) VALUES(?,?,?,?)");$s->execute([$d['name'],$d['phone'],$d['email'],password_hash($d['password'],PASSWORD_DEFAULT)]);echo json_encode(['success'=>true,'message'=>'Account created. You can now login.']);exit;}if($a==='login'){$s=$p->prepare("SELECT id,name,email,password_hash FROM users WHERE email=? AND active=1");$s->execute([$d['email']??'']);$u=$s->fetch(PDO::FETCH_ASSOC);if(!$u||!password_verify($d['password']??'',$u['password_hash']))throw new Exception('Invalid email or password.');$_SESSION['user_id']=$u['id'];$_SESSION['user_name']=$u['name'];echo json_encode(['success'=>true,'message'=>'Login successful.']);exit;}throw new Exception('Unknown action');}catch(Throwable $e){http_response_code(400);echo json_encode(['success'=>false,'error'=>$e->getMessage()]);}